import * as T from 'three';
import {createGarden,STOPS,SPAWN} from './world.js';
import {createExplorationNavigation} from './navigation.js';
const canvas=document.querySelector('#sea'),$=s=>document.querySelector(s),motion=matchMedia('(prefers-reduced-motion:reduce)');let ready=false,ambientPaused=false,time=0,last=null,pointer=null;
try{
 const gl=canvas.getContext('webgl2',{antialias:true,alpha:false});if(!gl)throw Error('WebGL2 unavailable');
 const renderer=new T.WebGLRenderer({canvas,context:gl,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=.95;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(61,1,.08,500),world=createGarden(scene);
 const nav=createExplorationNavigation({stops:STOPS,spawn:SPAWN,resolvePosition:p=>world.resolve(p),movePosition:(p,old)=>world.move(p,old),regionAt:p=>p[2]>-38?'珊瑚门廊':p[2]>-112?'虹色礁庭':'月弧峡湾'});nav.setReduced(motion.matches);nav.reset();
 const apply=()=>{const p=nav.pose();camera.position.fromArray(p.position);camera.lookAt(new T.Vector3(...p.target));camera.updateMatrixWorld()};
 function resize(){renderer.setSize(innerWidth,innerHeight,false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();apply()}resize();window.addEventListener('resize',resize);
 function sync(){const r=nav.getState(),index=r.mode==='free'?STOPS.reduce((best,s,i)=>Math.hypot(s.position[0]-r.position[0],s.position[2]-r.position[2])<Math.hypot(STOPS[best].position[0]-r.position[0],STOPS[best].position[2]-r.position[2])?i:best,0):Math.min(5,Math.round(r.progress*5));$('#placeNo').textContent=String(index+1).padStart(2,'0')+' / 06';$('#placeName').textContent=STOPS[index].label;$('#modeLabel').textContent=r.mode==='free'?'自由探索':r.mode==='completed'?'导览完成 · 随时再次出发':r.paused?'导览已暂停':'沿着光，继续游';$('#tour').innerHTML=(r.mode==='completed'?'重播 72 秒导览':'开始 72 秒导览')+' <span>↗</span>';$('#pause').textContent=r.paused?'继续':'暂停';$('#pause').disabled=r.mode==='completed';$('#progress').value=Math.round(r.progress*100);$('#progress').disabled=r.mode==='free';$('#time').textContent=r.mode==='free'?'自由探索':Math.round(r.elapsed)+' / 72 秒';document.body.classList.toggle('moving',r.mode!=='free'||r.elapsed>0);document.querySelectorAll('[data-stop]').forEach(b=>b.setAttribute('aria-current',String(Number(b.dataset.stop)===index)))}
 $('#tour').onclick=()=>{nav.startTour();last=null;apply();sync()};$('#free').onclick=()=>{nav.free();apply();sync()};$('#pause').onclick=()=>{nav.togglePause();sync()};$('#home').onclick=()=>{nav.reset();apply();sync()};$('#progress').oninput=e=>{nav.request(Number(e.target.value)/100);apply();sync()};document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>{nav.request(Number(b.dataset.stop)/5);apply();sync()});
 $('#more').onclick=()=>{const d=$('#details');d.hidden=!d.hidden;$('#more').setAttribute('aria-expanded',String(!d.hidden))};$('#ambient').onclick=()=>{ambientPaused=!ambientPaused;world.setPaused(ambientPaused);$('#ambient').textContent=ambientPaused?'继续环境动态':'暂停环境动态'};
 const menu=$('#previousMenu'),menuButton=$('#previous');
 function closePrevious(restoreFocus=false){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');if(restoreFocus)menuButton.focus({preventScroll:true})}
 menuButton.onclick=()=>{if(!menu.hidden){closePrevious();return}nav.stop();menu.hidden=false;menuButton.setAttribute('aria-expanded','true');$('#closePrevious').focus({preventScroll:true})};$('#closePrevious').onclick=()=>closePrevious(true);
 document.addEventListener('pointerdown',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!menuButton.contains(e.target))closePrevious()});document.addEventListener('keydown',e=>{if(e.code==='Escape'&&!menu.hidden){e.preventDefault();closePrevious(true)}});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>closePrevious()));
 const supported=['KeyW','KeyS','KeyA','KeyD','KeyQ','KeyE','ShiftLeft','ShiftRight','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'];canvas.addEventListener('keydown',e=>{if(supported.includes(e.code)){e.preventDefault();if(!e.repeat||!motion.matches)nav.key(e.code,true)}else if(e.code==='Space'){e.preventDefault();nav.togglePause()}else if(e.code==='Home'){e.preventDefault();nav.reset()}else if(e.code==='KeyR')nav.resetLook();apply();sync()});canvas.addEventListener('keyup',e=>nav.key(e.code,false));canvas.addEventListener('blur',()=>nav.stop());
 canvas.addEventListener('pointerdown',e=>{if(pointer)return;canvas.focus({preventScroll:true});nav.free();pointer={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(pointer?.id!==e.pointerId)return;nav.look((e.clientX-pointer.x)*.004,(pointer.y-e.clientY)*.003);pointer={id:e.pointerId,x:e.clientX,y:e.clientY};apply()});for(const event of['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,()=>{pointer=null});
 document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);nav.key(b.dataset.key,true);apply();sync()});for(const event of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>nav.key(b.dataset.key,false))});
 window.addEventListener('blur',()=>{nav.pause(true);nav.stop();last=null});document.addEventListener('visibilitychange',()=>{last=null;if(document.hidden){nav.pause(true);nav.stop()}});motion.addEventListener('change',()=>{nav.setReduced(motion.matches);last=null});
 ready=true;$('#loading').hidden=true;sync();let frames=0;renderer.setAnimationLoop(ms=>{const dt=last===null?0:Math.max(0,(ms-last)/1000);last=ms;if(document.hidden)return;nav.tick(dt);if(!ambientPaused&&!motion.matches)time+=Math.min(dt,.1);apply();world.update(time,camera);renderer.render(scene,camera);frames++;sync()});
 window.reefGarden={scene,camera,renderer,world,navigation:nav,getState:()=>({ready,camera:camera.position.toArray(),target:nav.pose().target,route:nav.getState(),time,ambientPaused,frames,stats:world.stats,renderer:{calls:renderer.info.render.calls,triangles:renderer.info.render.triangles}})};
 window.addEventListener('pagehide',()=>{renderer.setAnimationLoop(null);world.dispose();renderer.dispose()});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();renderer.setAnimationLoop(null);$('#error').hidden=false});
}catch(e){console.error('Reef garden failed',e);$('#loading').hidden=true;$('#error').hidden=false;window.reefGardenFailure=String(e)}
